-- International playable leagues for the 2026/27 career universe.
ALTER TABLE divisions ADD COLUMN IF NOT EXISTS country_code TEXT NOT NULL DEFAULT 'NED';
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,tier=EXCLUDED.tier,country_code=EXCLUDED.country_code;
ON CONFLICT (id) DO UPDATE SET division_id=EXCLUDED.division_id,name=EXCLUDED.name,city=EXCLUDED.city,reputation=EXCLUDED.reputation,team_strength=EXCLUDED.team_strength;
